\label{def:equinormed}
Let $(E,
orm{\cdot}_E)$ be a normed space equipped with a family $ igl\{
orm{\cdot}_i igr\}_{i \in I}$ of semi-norms satisfying conditions~	extbf{	extup{(A1)}} and~	extbf{	extup{(A2)}}.
A non-empty subset $A$ of $E$ is called \emph{equinormed} (or more precisely, \emph{equinormed with respect to the family $ igl\{
orm{\cdot}_i igr\}_{i \in I}$}) if for every $\varepsilon>0$ there exists an index $k \in I$ such that $
orm{x}_E\leq \varepsilon + 
orm{x}_k$ for all $x \in A$.

\label{thm:compactness_ver2}
Let $(E,\norm{\cdot}_E)$ be a normed space equipped with a family $\bigl\{\norm{\cdot}_i\bigr\}_{i \in I}$ of semi-norms satisfying conditions~\textbf{\textup{(A1)}} and~\textbf{\textup{(A2)}}. Furthermore, assume that 
\begin{enumerate}
 \item[\textbf{\textup{(A4)}}] for each bounded sequence $(x_n)_{n \in \mathbb N}$ of elements of $E$ there is a subsequence $(x_{n_k})_{k \in \mathbb N}$ which is Cauchy with respect to each semi-norm $\norm{\cdot}_i$.\footnote{We keep the numbering of conditions the same is in \cite{GKM}}
\end{enumerate}
Then, a non-empty subset $A$ of $E$ is precompact if and only if it is bounded and the set $A-A$ is equinormed.

\label{exh:fun:representation}
Assume now we have a family $\mathcal{F}$ of finite sets covering $\mathbb{N}$ (we neither assume that it is compact nor even hereditary).
Then there exists a subspace of a linear space $BC(K)$ of bounded and continuous functions $f\colon K\to\mathbb{R}$ with pointwise convergence topology, which is isometric to the space $\mathrm{EXH}(\mathcal{F})$.

\label{compact:bc}
 The set $A\subset \mathrm{EXH}(\mathcal{F})$ (i.e. $\Phi(A)\subset BC(K)$) is relatively compact iff 
 \begin{enumerate}
\item[(\ref{compact:bc}.1)] for each $\eta\in K$ the set $\{\Phi(a)(\eta) : a\in A\}\subset\mathbb{R}$ is bounded;
     \item[(\ref{compact:bc}.2)] for any $\varepsilon>0$ there exists the finite partition of the domain    $K=\bigcup_{i=1}^N K_i$ consisting of open sets $K_i\subset K$ such that 
 \[
 \forall_{\xi,\eta\in K_i} \forall_{a\in A} |\Phi(a)(\xi)-\Phi(a)(\eta)|<\varepsilon.
 \]
 \end{enumerate}

\label{th:compact:exh}
The following conditions are equivalent for any bounded set $A\subset \mathrm{EXH}(\mathcal{F})$: \begin{itemize}
    \item[(\ref{th:compact:exh}.1)] the set $A$ is relatively compact;
    \item[(\ref{th:compact:exh}.2)] for any $\varepsilon>0$ there exists such $n\in\mathbb{N}$ that 
    \[
    \left\Vert a\cdot\mathbbm{1}_{[n+1,+\infty)}\right\Vert_\mathcal{F} = \sup_{F\in\mathcal{F}}\sum_{k\in [n+1,+\infty)\cap F} |a_k|<\varepsilon,
    \]
    for all $a\in A$.
\end{itemize}

\label{lem:exh:compact:cond}
Assume the family $\mathcal{F}$ is hereditary. The following conditions are equivalent for a bounded set $A\subset\mathrm{EXH}(\mathcal{F})$:
\begin{itemize}
\item[(i)] the set $A-A$ is equinormed;
\item[(ii)] for any $\varepsilon>0$ there exists such $n\in\mathbb{N}$ that 
    \[
    \sum_{k\in [n+1,+\infty)\cap F} |a_k|<\varepsilon,
    \]
    for all $F\in\mathcal{F}$ and all $a\in A$.    
\end{itemize}

\label{th:compact:exh:2}
Assume the family $\mathcal{F}$ is hereditary. The following conditions are equivalent for any bounded set $A\subset \mathrm{EXH}(\mathcal{F})$: \begin{itemize}
    \item[(\ref{th:compact:exh:2}.1)] the set $A$ is relatively compact;
    \item[(\ref{th:compact:exh:2}.2)] for any $\varepsilon>0$ there exists such $n\in\mathbb{N}$ that 
    \[
    \sum_{k\in [n+1,+\infty)\cap F} |a_k|<\varepsilon,
    \]
    for all $F\in\mathcal{F}$ and all $a\in A$. 
\end{itemize}

\label{compact:fin:a-a}
 The set $A\subset \mathrm{FIN}(\mathcal{F})$  is relatively compact iff 
 \begin{enumerate}
\item[(\ref{compact:fin:a-a}.1)] it is bounded;
\item[(\ref{compact:fin:a-a}.2)] for any $\varepsilon>0$ there exists such $N\in\mathbb{N}$ that for all $a,b\in A$
\[
\sup_{F\in\mathcal{F} } \sum_{k\in F\cap[1,N]} |a_k-b_k| \geq \sup_{F\in\mathcal{F} } \sum_{k\in F} |a_k-b_k| - \varepsilon.
\]
 \end{enumerate}

\label{th:compact:b}
 The set $A\subset \mathrm{FIN}(\mathcal{F})$ (i.e. $\Phi(A)\subset B(K)$) is relatively compact iff 
 \begin{enumerate}
\item[(\ref{th:compact:b}.1)] for each $\eta\in K$ the set $\{\Phi(a)(\eta) : a\in A\}\subset\mathbb{R}$ is bounded;
     \item[(\ref{th:compact:b}.2)] for any $\varepsilon>0$ there exists the finite cover of the domain    $K=\bigcup_{i=1}^N K_i$ into sets $K_i\subset K$ such that 
 \[
 \forall_{\xi,\eta\in K_i} \forall_{a\in A} |\Phi(a)(\xi)-\Phi(a)(\eta)|<\varepsilon.
 \]
 \end{enumerate}

\label{prop:lp:problems}
The following equalities hold:
\begin{itemize}
    \item[(i)] $\mu^*(\mathcal{S},\mathcal{P}) = \max\{ \sum_{i=1}^N x_i : \forall_{P\in \mathcal{P}} \sum_{j\in\ P} x_j \leq 1 \wedge \forall_{j\in\{1,...,N\}} x_j\geq 0 \} = $
    \[
    \max\{ \sum_{i=1}^N x_i : \forall_{P\in \mathcal{P}} \sum_{j=1}^N x_j\mathbbm{1}_P(j) \leq 1 \wedge \forall_{j\in\{1,...,N\}} x_j\geq 0 \};
    \]
    \item[(ii)] $\nu^*(\mathcal{S},\mathcal{P}) = \min\{ \sum_{j=1}^M y_j : \forall_{s\in\mathcal{S}} \sum_{j : s\in P_j} y_j \geq 1 \wedge \forall_{j\in\{1,...,N\}} y_j\geq 0\}=$ 
    \[
    \min\{ \sum_{j=1}^M y_j : \forall_{s\in\mathcal{S}} \sum_{j=1}^M y_j\mathbbm{1}_{P_j}(s) \geq 1 \wedge \forall_{j\in\{1,...,N\}} y_j\geq 0\}.
    \]
\end{itemize}
